import lottie from 'lottie-web';

export function initPlaygroundAnimations() {

  const lottieContainer = document.querySelector('#lottie-playground');

  if (lottieContainer) {
    lottie.loadAnimation({
      container: lottieContainer, // The div to load into
      renderer: 'svg',
      loop: true,
      autoplay: true,
      path: '/lottie/cooking.json' // The same animation file
    });
  }
}